<?php
$rows=[];try{$rows=Database::query("SELECT l.id,l.created_at,l.event_type,l.entity_type,l.entity_id,l.ip_address,l.request_id,l.impersonation_session_id,COALESCE(a.name,e.name,'System') actor_name,e.name effective_name,b.name branch_name FROM security_audit_logs l LEFT JOIN users a ON a.id=l.actor_user_id LEFT JOIN users e ON e.id=l.effective_user_id LEFT JOIN branches b ON b.id=l.branch_id ORDER BY l.created_at DESC LIMIT 200")->fetchAll();}catch(Throwable $e){Security::reportException($e,'security_logs');}
?>
<section class="page-heading"><div><span class="eyebrow">SECURITY</span><h1>Security Logs</h1><p>Recent authentication, permission, inventory, sales and impersonation audit events.</p></div></section>
<section class="card table-card"><div class="card-header"><div><h2>Latest Events</h2><p>Most recent 200 audit records.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date / Time</th><th>Event</th><th>Actual Actor</th><th>Acting As</th><th>Branch</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e(date('M j, Y • g:i A',strtotime($r['created_at']))) ?></td><td><strong><?= e($r['event_type']) ?></strong><span class="table-subtext"><?= e(trim(($r['entity_type']?:'').' '.($r['entity_id']?:''))) ?></span></td><td><?= e($r['actor_name']) ?></td><td><?= e($r['effective_name']?:'—') ?><?php if($r['impersonation_session_id']):?><span class="table-subtext">Impersonated</span><?php endif;?></td><td><?= e($r['branch_name']?:'—') ?></td><td><?= e($r['ip_address']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state small"><strong>No security logs available.</strong></div></td></tr><?php endif;?></tbody></table></div></section>
